<?php
 namespace QQWorld\Shipping\Controller\Adminhtml\Shipment; use QQWorld\Backend\App\Action; use QQWorld\Framework\App\ResponseInterface; use QQWorld\Framework\App\Filesystem\DirectoryList; use QQWorld\Framework\Model\ResourceModel\Db\Collection\AbstractCollection; use QQWorld\Ui\Component\MassAction\Filter; use QQWorld\Backend\App\Action\Context; use QQWorld\Shipping\Model\Shipping\LabelGenerator; use QQWorld\Framework\App\Response\Http\FileFactory; use QQWorld\Framework\Controller\ResultInterface; use QQWorld\Sales\Model\ResourceModel\Order\Shipment\CollectionFactory; class MassPrintShippingLabel extends \QQWorld\Sales\Controller\Adminhtml\Order\AbstractMassAction { const ADMIN_RESOURCE = 'QQWorld_Sales::shipment'; protected $labelGenerator; protected $fileFactory; public function __construct( Context $context, Filter $filter, FileFactory $fileFactory, LabelGenerator $labelGenerator, CollectionFactory $collectionFactory ) { $this->collectionFactory = $collectionFactory; $this->fileFactory = $fileFactory; $this->labelGenerator = $labelGenerator; parent::__construct($context, $filter); } protected function massAction(AbstractCollection $collection) { $labelsContent = []; if ($collection->getSize()) { foreach ($collection as $shipment) { $labelContent = $shipment->getShippingLabel(); if ($labelContent) { $labelsContent[] = $labelContent; } } } if (!empty($labelsContent)) { $outputPdf = $this->labelGenerator->combineLabelsPdf($labelsContent); return $this->fileFactory->create( 'ShippingLabels.pdf', $outputPdf->render(), DirectoryList::VAR_DIR, 'application/pdf' ); } $this->messageManager->addError(__('There are no shipping labels related to selected shipments.')); return $this->resultRedirectFactory->create()->setPath('sales/shipment/'); } } 